CREATE OR REPLACE FUNCTION public.post_text_prohibited(_text text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT lower(coalesce(_text,'')) ~ '(^|[^a-z0-9_])(fuck|bitch|bastard|asshole|motherfucker|madarchod|behenchod|bhenchod|chutiya|randi|gandu|harami|lanja|lanjakodaka|dengu|dengey|pooku|modda|sulli)([^a-z0-9_]|$)|లంజ|దెంగ|పూకు|మొడ్డ|సుల్లి|promote terrorism|join isis|terror attack planning|ఉగ్రదాడి ప్రణాళిక|ఉగ్రవాదాన్ని ప్రోత్సహించ|దేశాన్ని నాశనం చేయండి|భారత్ ముర్దాబాద్' $$;
CREATE OR REPLACE FUNCTION public.guard_bad_words() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF public.post_text_prohibited(concat_ws(' ',NEW.title,NEW.description,NEW.skill,NEW.location,NEW.goods_type,NEW.from_place,NEW.to_place,NEW.service_type,NEW.public_brand)) THEN RAISE EXCEPTION 'BAD_CONTENT'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.chat_bell_ready(_other uuid,_post uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND (EXISTS(SELECT 1 FROM public.directed_bell_usage WHERE rings>0 AND ((sender_id=auth.uid() AND recipient_id=_other) OR (sender_id=_other AND recipient_id=auth.uid()))) OR EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE board_rang_at IS NOT NULL AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) OR EXISTS(SELECT 1 FROM public.post_chat_pairs pair JOIN public.post_bell_interests i ON i.post_id=pair.post_id AND i.user_id=pair.member_id WHERE (_post IS NULL OR pair.post_id=_post) AND ((pair.member_id=auth.uid() AND pair.owner_id=_other) OR (pair.owner_id=auth.uid() AND pair.member_id=_other)))) $$;
REVOKE ALL ON FUNCTION public.chat_bell_ready(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.chat_bell_ready(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') THEN true WHEN NOT public.profile_ready_for_actions(auth.uid()) OR NOT public.chat_bell_ready(_other,_post) THEN false WHEN public.incoming_bell_reply_allowed(_other,_post) THEN true WHEN _post IS NOT NULL THEN EXISTS(SELECT 1 FROM public.post_chat_pairs c JOIN public.posts p ON p.id=c.post_id WHERE c.post_id=_post AND ((c.member_id=auth.uid() AND c.owner_id=_other) OR (c.owner_id=auth.uid() AND c.member_id=_other)) AND (p.module<>'vehicle' OR public.vehicle_contact_access(auth.uid()))) ELSE public.free_work_chat(_other) OR EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.bell_board_chat_pairs c WHERE ((c.member_id=auth.uid() AND c.owner_id=_other) OR (c.owner_id=auth.uid() AND c.member_id=_other)) AND (public.vehicle_contact_access(auth.uid()) OR EXISTS(SELECT 1 FROM public.service_requests s WHERE s.id=c.interest_id) OR EXISTS(SELECT 1 FROM public.post_bell_interests b JOIN public.posts p ON p.id=b.post_id WHERE b.id=c.interest_id AND p.module='job'))) OR (public.vehicle_contact_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
CREATE OR REPLACE FUNCTION public.ring_chat(_other uuid,_post uuid DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE vehicle boolean:=true; BEGIN IF auth.uid() IS NULL OR auth.uid()=_other OR NOT public.account_allowed(auth.uid()) OR NOT public.account_allowed(_other) THEN RAISE EXCEPTION 'ACCOUNT_REQUIRED'; END IF;
IF _post IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_post AND p.user_id=_other AND public.post_listing_visible(p)) THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; PERFORM public.ring_post(_post); RETURN public.can_post_chat(_post,_other); END IF;
IF NOT EXISTS(SELECT 1 FROM public.free_work_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) AND NOT EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) AND NOT EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) AND NOT EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) AND NOT EXISTS(SELECT 1 FROM public.bell_board_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) THEN RAISE EXCEPTION 'CHAT_PAIR_REQUIRED'; END IF;
vehicle:=NOT (EXISTS(SELECT 1 FROM public.free_work_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.bell_board_chat_pairs c JOIN public.post_bell_interests b ON b.id=c.interest_id JOIN public.posts p ON p.id=b.post_id WHERE p.module='job' AND ((c.member_id=auth.uid() AND c.owner_id=_other) OR (c.owner_id=auth.uid() AND c.member_id=_other))));
PERFORM public.consume_directed_bell(_other,vehicle); IF NOT public.can_post_chat(NULL,_other) THEN RAISE EXCEPTION 'CHAT_PAIR_REQUIRED'; END IF;
INSERT INTO public.notifications(user_id,message) VALUES(_other,'ఒకరు గంట నొక్కారు; మీ సంభాషణలో చూడండి.'); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.ring_chat(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ring_chat(uuid,uuid) TO authenticated;
